export interface SeedData {
  businesses: Omit<Business, 'createdAt' | 'ratingAvg' | 'ratingCount'>[];
  staff: Staff[];
  services: Service[];
  staffServices: StaffService[];
  businessHours: BusinessHours[];
  staffHours: StaffHours[];
  clients: SeedClient[];
  appointments: SeedAppointment[];
  payments: SeedPayment[];
  reviews: SeedReview[];
  notes: { id: string; clientId: string; body: string }[];
}

export const SEED_CANDIDATES = 270;
export const SEED_APPOINTMENTS = 200;

const REF_ALPHABET = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
export function makeReference(rand: () => number = Math.random): string {
  let s = 'KZ-';
  for (let i = 0; i < 5; i++) s += REF_ALPHABET[Math.floor(rand() * REF_ALPHABET.length)];
  return s;
}

export function generateSeed(): SeedData {
  const rand = mulberry32(20261003);
  const pick = <T,>(arr: readonly T[]) => arr[Math.floor(rand() * arr.length)];
  const between = (a: number, b: number) => a + Math.floor(rand() * (b - a + 1));
  const roundTo = (n: number, step: number) => Math.round(n / step) * step;

  const data: SeedData = { businesses: [], staff: [], services: [], staffServices: [], businessHours: [], staffHours: [], clients: [], appointments: [], payments: [], reviews: [], notes: [] };
  let staffN = 0;
  let serviceN = 0;

  SALONS.forEach((tpl, i) => {
    const city = CITIES[tpl.city];
    const country = countryByCode(city.countryCode);
    const id = uuidFrom('b0000000', i + 1);
    const local = (len: number) => {
      let s = '0' + String(between(1, 9));
      while (s.length < len) s += String(between(0, 9));
      return s.slice(0, len);
    };
    const phone = country.dialCode + local(country.phoneLength);
    data.businesses.push({
      id,
      slug: slugify(`${tpl.name}-${city.name}`),
      name: tpl.name,
      cityId: city.id,
      district: tpl.district,
      address: tpl.address,
      lat: tpl.lat,
      lng: tpl.lng,
      phone,
      whatsapp: phone,
      description: tpl.description,
      photoSeeds: [i * 5 + 1, i * 5 + 2, i * 5 + 3, i * 5 + 4, i * 5 + 5],
      photoUrls: [],
      instantBooking: tpl.instant,
      audience: tpl.audience,
      slotStepMin: 15,
      minNoticeMin: 60,
      depositRule: tpl.deposit,
      paymentOptions: tpl.options,
      paymentMethods: tpl.methods,
      cancellationHours: 24,
      status: 'active',
      isDemo: true,
      ownerId: i === 0 ? DEMO_ACCOUNTS.owner.id : null,
    });

    const h = HOURS[tpl.hours];
    for (const d of h.days) data.businessHours.push({ businessId: id, weekday: d, opens: h.opens, closes: h.closes, breakStart: h.br?.[0] ?? null, breakEnd: h.br?.[1] ?? null });
    if (h.sunday) data.businessHours.push({ businessId: id, weekday: 0, opens: h.sunday[0], closes: h.sunday[1], breakStart: null, breakEnd: null });

    const staffIds: string[] = [];
    tpl.staff.forEach(([name, role], k) => {
      const sid = uuidFrom('5a000000', ++staffN);
      staffIds.push(sid);
      data.staff.push({ id: sid, businessId: id, name, role, color: STAFF_COLORS[k % STAFF_COLORS.length], photoUrl: null, sort: k, active: true });
    });
    // Third professional works a shorter week (own hours), to exercise staff_hours.
    for (const d of h.days.slice(1)) data.staffHours.push({ staffId: staffIds[2], weekday: d, starts: h.opens, ends: minutesToTime(timeToMinutes(h.closes) - 60) });

    tpl.services.forEach((key, k) => {
      const t = T[key];
      const svid = uuidFrom('5e000000', ++serviceN);
      data.services.push({
        id: svid,
        businessId: id,
        categoryId: cat(t.cat),
        name: t.name,
        description: t.desc,
        durationMin: t.dur,
        price: roundTo(between(t.price[0], t.price[1]), 500),
        depositRule: t.deposit ?? null,
        active: true,
        sort: k,
      });
      // Staff 0 does everything; others do a rotating subset (every service has ≥ 2 pros).
      data.staffServices.push({ staffId: staffIds[0], serviceId: svid });
      data.staffServices.push({ staffId: staffIds[1 + (k % 2)], serviceId: svid });
      if (k % 3 === 0) data.staffServices.push({ staffId: staffIds[2 - (k % 2)], serviceId: svid });
    });
  });
  // De-duplicate staff_services pairs.
  data.staffServices = data.staffServices.filter((x, i, arr) => arr.findIndex((y) => y.staffId === x.staffId && y.serviceId === x.serviceId) === i);

  // 100 clients, 10 per salon. The demo client account is a client of salons 1, 2 and 5.
  let clientN = 0;
  data.businesses.forEach((b, bi) => {
    const country = countryByCode(CITIES.find((c) => c.id === b.cityId)!.countryCode);
    for (let k = 0; k < 10; k++) {
      const isDemoClient = k === 0 && [0, 1, 4].includes(bi);
      const firstName = isDemoClient ? DEMO_ACCOUNTS.client.firstName : pick(FIRST);
      const lastName = isDemoClient ? DEMO_ACCOUNTS.client.lastName : pick(LAST);
      let num = '0' + String(between(1, 7));
      while (num.length < country.phoneLength) num += String(between(0, 9));
      data.clients.push({
        id: uuidFrom('c1000000', ++clientN),
        businessId: b.id,
        profileId: isDemoClient ? DEMO_ACCOUNTS.client.id : null,
        firstName,
        lastName,
        phone: isDemoClient ? DEMO_ACCOUNTS.client.phone : country.dialCode + num,
        email: isDemoClient ? DEMO_ACCOUNTS.client.email : '',
        createdDayOffset: -between(1, 240),
      });
    }
  });
  data.notes.push({ id: uuidFrom('20000000', 1), clientId: data.clients[1].id, body: 'Préfère les mèches 1B. Cuir chevelu sensible.' });
  data.notes.push({ id: uuidFrom('20000000', 2), clientId: data.clients[11].id, body: 'Toujours le samedi matin. Dégradé bas.' });

  // 270 candidate appointments without overlaps per staff. Weekdays are only known once the seed is
  // anchored to a real "today", so materialisation keeps the first 200 that fall inside opening hours
  // (see isSeedAppointmentValid, mirrored in the generated seed.sql).
  const busy = new Map<string, [number, number][]>();
  let apptN = 0;
  let payN = 0;
  let reviewN = 0;
  const usedRefs = new Set<string>();
  let guard = 0;
  while (data.appointments.length < SEED_CANDIDATES && guard++ < 20000) {
    // The demo manager's salon (index 0) is the busiest, with a dense fortnight around today.
    // First 50 candidates: 5 completed, reviewed past visits per salon, so every salon has history.
    const forced = data.appointments.length < 50;
    const bi = forced ? data.appointments.length % 10 : rand() < 0.35 ? 0 : between(1, 9);
    const b = data.businesses[bi];
    const dayOffset = forced ? between(-30, -1) : bi === 0 && rand() < 0.7 ? between(-7, 7) : between(-30, 13);
    const tplHours = HOURS[SALONS[bi].hours];
    const services = data.services.filter((s) => s.businessId === b.id);
    const nServices = rand() < 0.2 ? 2 : 1;
    const chosen: Service[] = [];
    while (chosen.length < nServices) {
      const s = pick(services);
      if (!chosen.includes(s)) chosen.push(s);
    }
    const duration = chosen.reduce((s, x) => s + x.durationMin, 0);
    const staffForAll = data.staff.filter((st) => st.businessId === b.id && chosen.every((sv) => data.staffServices.some((x) => x.staffId === st.id && x.serviceId === sv.id)));
    if (!staffForAll.length) continue;
    const staff = pick(staffForAll);
    const open = timeToMinutes(tplHours.opens);
    const close = timeToMinutes(tplHours.closes) - (staff.sort === 2 ? 60 : 0);
    const brk = tplHours.br ? [timeToMinutes(tplHours.br[0]), timeToMinutes(tplHours.br[1])] : null;
    const latest = close - duration;
    if (latest < open) continue;
    const start = open + Math.floor(rand() * ((latest - open) / 15 + 1)) * 15;
    const end = start + duration;
    if (brk && start < brk[1] && brk[0] < end) continue;
    const key = `${staff.id}|${dayOffset}`;
    const list = busy.get(key) ?? [];
    if (list.some(([s, e]) => start < e && s < end)) continue;
    // Future appointments: keep today's slots after "now"-ish by pushing them to the afternoon.
    if (dayOffset === 0 && start < 14 * 60) continue;
    list.push([start, end]);
    busy.set(key, list);

    const clientsOfB = data.clients.filter((c) => c.businessId === b.id);
    // Make sure the demo client has history: first appointments of salons 0/1/4 go to them.
    const demoClient = clientsOfB.find((c) => c.profileId);
    const client = demoClient && data.appointments.filter((a) => a.clientId === demoClient.id).length < 3 && rand() < 0.5 ? demoClient : pick(clientsOfB);

    const past = dayOffset < 0;
    let status: AppointmentStatus;
    const r = rand();
    if (forced) status = 'completed';
    else if (past) status = r < 0.8 ? 'completed' : r < 0.87 ? 'no_show' : 'cancelled';
    else status = r < 0.9 ? 'confirmed' : 'cancelled';

    const total = chosen.reduce((s, x) => s + x.price, 0);
    const rule = b.depositRule;
    const deposit = rule.type === 'none' ? 0 : rule.type === 'fixed' ? Math.min(total, rule.value) : rule.type === 'percent' ? Math.ceil((total * rule.value) / 10000) * 100 : total;

    let paymentStatus: PaymentStatus;
    let amountPaid = 0;
    const optionRoll = rand();
    if (status === 'completed') {
      paymentStatus = 'paid';
      amountPaid = total;
    } else if (status === 'cancelled') {
      paymentStatus = deposit > 0 && optionRoll < 0.5 ? 'refunded' : 'pay_on_site';
    } else if (status === 'no_show') {
      paymentStatus = deposit > 0 ? 'deposit_paid' : 'pay_on_site';
      amountPaid = deposit;
    } else {
      if (b.paymentOptions.includes('on_site') && optionRoll < 0.5) paymentStatus = 'pay_on_site';
      else if (b.paymentOptions.includes('deposit') && deposit > 0 && optionRoll < 0.8) {
        paymentStatus = 'deposit_paid';
        amountPaid = deposit;
      } else {
        paymentStatus = 'paid';
        amountPaid = total;
      }
    }

    let ref = makeReference(rand);
    while (usedRefs.has(ref)) ref = makeReference(rand);
    usedRefs.add(ref);

    const id = uuidFrom('a1000000', ++apptN);
    data.appointments.push({
      id, reference: ref, businessId: b.id, staffId: staff.id, clientId: client.id, profileId: client.profileId,
      dayOffset, time: minutesToTime(start), durationMin: duration, serviceIds: chosen.map((s) => s.id),
      status, paymentStatus, total, deposit, amountPaid, createdDayOffset: Math.min(dayOffset, 0) - between(1, 10),
    });

    const country = countryByCode(CITIES.find((c) => c.id === b.cityId)!.countryCode);
    if (amountPaid > 0 || paymentStatus === 'refunded') {
      const online = paymentStatus !== 'paid' || status !== 'completed' || rand() < 0.4;
      const method: PaymentMethod = online ? (b.paymentMethods.includes('card') && rand() < 0.2 ? 'card' : 'mobile_money') : 'cash';
      data.payments.push({
        id: uuidFrom('9a000000', ++payN), appointmentId: id, businessId: b.id,
        provider: method === 'cash' ? 'cash' : method === 'card' ? 'card' : pick(country.operators),
        method, amount: paymentStatus === 'refunded' ? deposit : amountPaid,
        status: paymentStatus === 'refunded' ? 'refunded' : 'succeeded', phone: method === 'mobile_money' ? client.phone : null,
      });
    }

    if (status === 'completed' && (forced || rand() < 0.55) && client.profileId !== DEMO_ACCOUNTS.client.id) {
      const rating = rand() < 0.65 ? 5 : rand() < 0.8 ? 4 : 3;
      data.reviews.push({
        id: uuidFrom('7e000000', ++reviewN), appointmentId: id, businessId: b.id, profileId: null,
        authorName: `${client.firstName} ${client.lastName.charAt(0)}.`, rating, comment: pick(REVIEW_TEXT),
        reply: rand() < 0.3 ? pick(REPLIES) : null, dayOffset: Math.min(-1, dayOffset + between(0, 2)),
      });
    }
  }
  return data;
}

/** True when a relative seed appointment lands inside the salon's (and staff's) hours for that weekday. */
export function isSeedAppointmentValid(
  a: Pick<SeedAppointment, 'businessId' | 'staffId' | 'time' | 'durationMin'>,
  weekday: number,
  hours: BusinessHours[],
  staffHours: StaffHours[],
): boolean {
  const bh = hours.find((h) => h.businessId === a.businessId && h.weekday === weekday);
  if (!bh) return false;
  const s = timeToMinutes(a.time);
  const e = s + a.durationMin;
  if (s < timeToMinutes(bh.opens) || e > timeToMinutes(bh.closes)) return false;
  if (bh.breakStart && bh.breakEnd && s < timeToMinutes(bh.breakEnd) && timeToMinutes(bh.breakStart) < e) return false;
  const own = staffHours.filter((h) => h.staffId === a.staffId);
  if (own.length) {
    const sh = own.find((h) => h.weekday === weekday);
    if (!sh || s < timeToMinutes(sh.starts) || e > timeToMinutes(sh.ends)) return false;
  }
  return true;
}
